mapper.update:
UPDATE game_exercise_room
   SET state_json = #{stateJson}, state_version = #{stateVersion}, status = #{status}
 WHERE id = #{roomId}

UPDATE game_exercise_room
   SET status = 'FINISHED', winner_user_id = #{winnerUserId}, winner_team = #{winnerTeam},
       finish_reason = #{reason}, state_json = #{stateJson}, state_version = #{stateVersion},
       finished_at = #{now}
 WHERE id = #{roomId}

UPDATE game_exercise_room
   SET status = 'CANCELLED', finish_reason = #{reason}, finished_at = #{now}
 WHERE id = #{roomId} AND status = 'WAITING'

UPDATE game_exercise_member
   SET score = #{score}, kills = #{kills}, deaths = #{deaths}, assists = #{assists}
 WHERE room_id = #{roomId} AND user_id = #{userId}

mapper.select:
SELECT * FROM game_exercise_member
 WHERE room_id = #{roomId}
 ORDER BY joined_at ASC
